INSERT INTO figure_text (figure_code, lang, name, description) VALUES
    ('THATCHER', 'es', 'Margaret Thatcher', 'Primera ministra del Reino Unido (1979-1990). Privatizaciones, recortes de impuestos y reducción del poder sindical.'),
