    ('FRIEDMAN', 'es', 'Milton Friedman', 'Economista estadounidense, premio Nobel. Defensor del libre mercado, el Estado mínimo y las libertades civiles.'),
    ('FRIEDMAN', 'ca', 'Milton Friedman', 'Economista nord-americà, premi Nobel. Defensor del lliure mercat, l’Estat mínim i les llibertats civils.'),
    ('FRIEDMAN', 'en', 'Milton Friedman', 'American Nobel-winning economist. Advocate of free markets, minimal government and civil liberties.'),
