    ('ROOSEVELT', 'en', 'Franklin D. Roosevelt', 'US President (1933-1945). The New Deal, social security and leadership in the Second World War.'),
    ('PALME', 'es', 'Olof Palme', 'Primer ministro de Suecia (1969-1976 y 1982-1986). Socialdemocracia, Estado del bienestar y política exterior independiente.'),
    ('PALME', 'ca', 'Olof Palme', 'Primer ministre de Suècia (1969-1976 i 1982-1986). Socialdemocràcia, Estat del benestar i política exterior independent.'),
    ('PALME', 'en', 'Olof Palme', 'Prime Minister of Sweden (1969-1976 and 1982-1986). Social democracy, the welfare state and an independent foreign policy.'),
    ('LUXEMBURG', 'es', 'Rosa Luxemburgo', 'Teórica y revolucionaria marxista (Polonia y Alemania). Defendió la revolución de masas y la democracia socialista; fue asesinada en 1919.'),
    ('LUXEMBURG', 'ca', 'Rosa Luxemburg', 'Teòrica i revolucionària marxista (Polònia i Alemanya). Va defensar la revolució de masses i la democràcia socialista; va ser assassinada el 1919.'),
    ('LUXEMBURG', 'en', 'Rosa Luxemburg', 'Marxist theorist and revolutionary (Poland and Germany). Championed mass revolution and socialist democracy; murdered in 1919.'),
    ('ALLENDE', 'es', 'Salvador Allende', 'Presidente de Chile (1970-1973). Vía democrática al socialismo; murió durante el golpe militar de Pinochet.'),
    ('ALLENDE', 'ca', 'Salvador Allende', 'President de Xile (1970-1973). Via democràtica al socialisme; va morir durant el cop militar de Pinochet.'),
    ('ALLENDE', 'en', 'Salvador Allende', 'President of Chile (1970-1973). A democratic road to socialism; died during Pinochet’s military coup.'),
    ('MONTSENY', 'es', 'Federica Montseny', 'Anarquista y ministra de Sanidad en la Segunda República (1936-1937). Defendió el comunismo libertario y los derechos de las mujeres.'),
    ('MONTSENY', 'ca', 'Federica Montseny', 'Anarquista i ministra de Sanitat a la Segona República (1936-1937). Va defensar el comunisme llibertari i els drets de les dones.'),
